export default [{"id":349,"question":"يسأل عن الصلاة في المسجد الحرام بمئة ألف صلاة، هل على الحرم أو على المسجد أو يعمّ مكة؟","title":"هل كل مكة تُعتبر حرماً؟","answer":"الجواب: الصحيح عام، بعض العلماء خصَّه بما حول الكعبة، والصحيح أنه عامٌّ، فالمسجد الحرام يعمّ الحرم كله، لكن كلما كان المسجد أكثر جماعةٍ كان أفضل، وما حول الكعبة يكون أفضل لكثرة الجماعة، وقربه من الكعبة، والخروج من الخلاف، ولكن الصحيح أنه يعمّ، فالمساجد التي في مكة لها المضاعفة، نرجو لها المضاعفة إن شاء الله، وهذا المعنى اختاره أبو العباس ابن تيمية وابن القيم وجماعة من المحدثين.","link":"https://binbaz.org.sa/fatwas/4438/هل-كل-مكة-تعتبر-حرما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0402.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":804,"question":"ما الأشهر الحرم؟ وما حكم مَن قتل صيدًا فيها؟ وما يجب عليه إذا قتل؟","title":"ما الأشهر الحرم؟ وما حكم قتل الصيد فيها؟","answer":"الجواب: الصيد ما يحرم على الإنسان إلا إذا كان مُحْرِمًا، ما هو في الشهر الحرام، إنما الصيد يَحْرُم على المُحْرِم، ويَحْرُم في أرض الحرم، حرم مكة والمدينة.\nوأما الأشهر الحرم فهي: رجب، وذو القعدة، وذو الحجة، والمحرم، هذه الأشهر الحرم، ثلاثة مُتوالية: ذو القعدة، وذو الحجة، ومحرم، هذا الذي نحن فيه شهر الله المحرم، والرابع منفرد بين جمادى وشعبان، وهو رجب.\nكان العرب يجتنبون فيها القتال، ويحذرون فيها القتال، ويُسافرون فيها من بلادٍ إلى بلادٍ، وبيَّن الله عظمتها بقوله جلَّ وعلا: إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ ذَلِكَ الدِّينُ الْقَيِّمُ فَلَا تَظْلِمُوا فِيهِنَّ أَنْفُسَكُمْ [التوبة:36] يعني: بالمعاصي والشُّرور وطاعة الشيطان، ما هو بالصيد، بالمعاصي والمخالفات.\nأما الصيد فهو حلالٌ في رجب، في ذي القعدة، أو في ذي الحجة، أو في المحرم، الصيد حلالٌ إذا كنتَ لستَ مُحْرِمًا، ولا في أرض الحرم، لكن لا تظلم نفسك فيها بالقتال الذي حرَّمه الله، أو بالمعاصي التي حرَّمها الله.\nوقد تنازع العلماء: هل هي باقية أو نُسخت؟ على قولين:\nالأكثرون على أنها نُسخت، وأن القتال فيها مباح، وأن المسلمين لهم أن يُجاهدوا عدوهم في الأشهر الحرم.\nوذهب بعضُ أهل العلم إلى أن القتال فيها باقٍ لم يُنسخ، كما قال تعالى: يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ [البقرة:217].\nوذكر ابنُ القيم في هذا المقام وفي هذا البحث وأطال فيه ونصره، وأنها باقية لم تُنسخ، أما قوله تعالى: فَإِذَا انْسَلَخَ الْأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ [التوبة:5] قال: هذه الآية قيل فيها: إنَّ المراد بالحرم الأربعة التي جعلها النبيُّ ﷺ لمن لا عهدَ له، أمهله أربعة أشهرٍ، فإذا مضت ولم يُسلم قُوتل، وليس المراد بها الأربعة المشهورة التي هي: رجب، وذو القعدة، وذو الحجة، والمحرم.","link":"https://binbaz.org.sa/fatwas/20792/ما-الاشهر-الحرم-وما-حكم-قتل-الصيد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0622ما هي الأشهر الحرم؟ وماحكم من قتل صيداً فيها؟ ابن باز فتاوى المحاضرات.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":892,"question":"هل الصلاة في أي مسجدٍ من المساجد الداخلة في حدود الحرم تُساوي أجر الصلاة في البيت الحرام؟","title":"هل مضاعفة الصلاة تعمُّ جميع مساجد مكة؟","answer":"الجواب: اختلف أهلُ العلم في هذا: منهم مَن قال: إن التَّضعيف يختصّ بما حول الكعبة. وقال آخرون من أهل العلم: إن التَّضعيف يعمّ جميع الحرم، وأن الصلاة في كل مسجدٍ من مساجد مكة خيرٌ من مئة ألف صلاةٍ فيما سواه، ولكن يمتاز ما حول الكعبة بمزيد فضلٍ من جهة: كثرة الجماعة، وقرب الكعبة ومُشاهدتها، وعدم الخلاف، فإنَّ التضعيف في محلِّ الكعبة محلُّ إجماعٍ، إنما الخلاف فيما خرج عن ذلك، فالذي صلَّى حول الكعبة يحصل له هذه الفضائل، مع الجزم بالمضاعفة إذا قبل الله منه.\nأما الصواب: فالصواب أنهم تعمّ، المضاعفة تعمّ المساجد كلها في مكة، أي في الحرم كله؛ لأنَّ كله يُسمَّى: المسجد الحرام، كل الحرم يُسمَّى: المسجد الحرام.","link":"https://binbaz.org.sa/fatwas/20935/هل-مضاعفة-الصلاة-تعم-جميع-مساجد-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0731هل الصلاة في أي مسجد من المساجد في الداخلة في حدود الحرم تساوي في الأجرالصلاةفي البيت الحرام.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":1222,"question":"هل الصَّلوات ثوابها يتضاعف بالمسجد الحرام فقط، أم في كل مكة، أم في كل الحرم؟ وبماذا يتميز المسجد الحرام على بقية مكة وسائر الحرم؟","title":"هل الثواب المضاعف للصلاة يعمُّ مكة كلها؟","answer":"الجواب:\nسبق في المحاضرة أنَّ الصواب أن المضاعفة تعمّ مكة كلها، تعمّ الحرم كله؛ لقوله ﷺ: صلاةٌ في مسجدي هذا خيرٌ من ألف صلاةٍ مما سواه، إلا المسجد الحرام، وصلاةٌ في المسجد الحرام خيرٌ من صلاةٍ في مسجدي هذا بمئة صلاةٍ، صار معناه: أنها بمئة ألف، الصلاة بالمسجد الحرام بمئة ألفٍ، وفي مسجد النبي ﷺ خيرٌ من ألف صلاةٍ مما سواه، وجاء في الحديث الآخر: وفي المسجد الأقصى بخمسمئة صلاةٍ، وجميع مكة ومساجدها كلها فيها مُضاعفة.  لكن ليس معناه أنه يجوز أن يُصلي في بيته ويترك الجماعة، لا، يجب أن يصلي مع الجماعة، لكن المضاعفة تحصل له إذا صلَّى في بيته تطوعات، أو فاتته الصلاةُ فصلَّى في بيته، لكن ما حول الكعبة يمتاز بكثرة الجمع، وفضل القُرب من الكعبة ومُشاهدتها، يمتاز بما شاء الله من الأجر .","link":"https://binbaz.org.sa/fatwas/21290/هل-الثواب-المضاعف-للصلاة-يعم-مكة-كلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1033هل الصلوات ثوابها يتضاعف في المسجد الحرام فقط أم في كل الحرم؟.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":1281,"question":"هل حُرمة المشاعر المقدسة مثل: عرفات ومنى ومُزدلفة، هل هي دائمة أم مُؤقتة بأيام الحج؟","title":"هل حرمة المشاعر دائمة أم مؤقتة بأيام الحج؟","answer":"الجواب:\nهي دائمة، الحرم كله دائم، السيئة فيه مضاعفة عظيمة، وعرفة ليست حرمًا، ولكنه مَشْعر يجب الحذر من امتهانه، أما مُزدلفة ومنى فهي حرمٌ، والله يقول: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ [الحج:25]، أما عرفة فهي مشعر، لكن ليس بحرمٍ، فينبغي للمؤمن أن يجتنب المعاصي فيها؛ لكونها محلّ عبادةٍ، هي محل الحج، ومحل اجتماع المسلمين، فينبغي البعد، ويُخشى عليه أن يكون مثل الحرم، هذا المشعر العظيم يُخشى عليه من الإثم، إذا فعل معصيةً تكون أكثر من معصية غيرها، وإلا فالمعصية فيها إثمٌ مطلقًا في أي مكانٍ، لكن في المشاعر أو في الحرم تكون أشدَّ -نسأل الله العافية.\nس: وإذا كانت حُرمتها دائمةً فإن أكثر المسلمين أو كثيرًا من المسلمين يذهبون إليها للنُّزهة، وربما تعمل فيها بعض المُنكرات؟\nالشيخ: المنكرات قد تُفعل حتى في بيوت مكة، حتى من داخل، الواجب الحذر، قد تُفعل المنكرات في البيت من داخلٍ -نسأل الله الهداية للجميع- فالواجب الحذر، الله يقول: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ، والواجب على الدولة منع ما ظهر من ذلك، سواء كان في منى، أو مزدلفة، أو عرفات، أو غير ذلك، منع المنكر الظاهر، على الهيئة أن تقوم بذلك حتى في غير مكة، وما خفي فإلى الله .","link":"https://binbaz.org.sa/fatwas/21324/هل-حرمة-المشاعر-داىمة-ام-موقتة-بايام-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1067هل حرم المشاعر المقدسة دائم أم مؤقتة بأيام الحج؟ ابن باز.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":1725,"question":"بالنسبة للحج: في بعض البلدان الإسلامية إذا وافق الوقوفُ بعرفة يوم الجمعة يقول علماء تلك البلدان: هذا الحج كأنَّ الإنسان حجَّ مع النبي، كأنَّ له أفضلية، حتى يكثر الحُجَّاجُ من تلك البلاد، فهل لهذا دليل؟","title":"هل الوقوفُ بعرفة يوم الجمعة له أفضلية؟","answer":"الجواب:\nماذا يفعلون؟\nس: الحُجَّاج يأتون بكثرة، يقولون: يوم الجمعة هذا له أفضلية عن بقية الأيام في وقوف عرفة؟\nج: يعني: يجتمعون في مساجدهم؟\nس: لا، يأتون إلى الحج؛ لأنَّهم يقولون: هذا أفضل من بقية ..؟\nج: لا؛ لأنها مزية وافقت حجّة النبي ﷺ، وإلا فالأحاديث ضعيفة فيها، لكن معناها أنها وافقت حجّة النبي ﷺ، فالنبي حجَّ في يوم الجمعة.\nس: يعني: له أفضلية؟\nج: نعم؛ لأنَّ فيه ساعةً مُستجابةً، بعد العصر.","link":"https://binbaz.org.sa/fatwas/21832/هل-الوقوف-بعرفة-يوم-الجمعة-له-افضلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا وافق الوقوفُ بعرفة يوم الجمعة هل له أفضلية.mp3","categories":["الوقوف بعرفة","فضائل الأزمنة والأمكنة"]},{"id":2323,"question":"إذا اعتمر الرجلُ في أول ليلةٍ من ليالي رمضان، فهل يشمله فضلُ عمرةٍ في رمضان وأنها تعدل حجةً أم أنَّ هذا في أيام رمضان؟","title":"وقت العمرة برمضان وحكم تكرارها وإهدائها","answer":"الجواب:\nنعم، كل رمضان من أوَّله إلى آخره.\nس: من أول ليلةٍ في رمضان؟\nج: نعم.\nس: يقول السائلُ: قمتُ بأداء عمرةٍ في شهر رجب، وأريد القيام بعمرةٍ في شهر رمضان المبارك -إن شاء الله تعالى- فأيّهما أفضل وأولى: أن أُهدي ثوابَ العمرة هذه لأمِّي التي ما زالت على قيد الحياة أم لخالي الذي توفَّاه الله؟\nج: إذا كانت أمُّك عاجزةً لا تستطيع أن تعتمر فهي أولى بالبِرِّ من الخال أو ميتةً.\nس: هل يجوز القيامُ بأكثر من عمرةٍ خلال العشر الأواخر من رمضان؟\nج: ما أعلم مانعًا، إلا إذا كانت فيها مُزاحمةٌ ومشقَّةٌ فتركها أولى.\nس: بالنسبة للعمرة: إذا انتفت منها المشقَّة هل يمكن للإنسان أن يُكررها في رمضان؟\nج: ما أعلم مانعًا، يقول ﷺ: العمرةُ إلى العمرة كفَّارةٌ لما بينهما، ما حدَّد حدًّا عليه الصلاة والسلام، لكن يُراعي عدم المشقة؛ لأنَّ بعض الناس تحصل عليهم زحمةٌ ومشقَّةٌ، فإذا كانت هناك زحمةٌ فتركها أوْلَى.","link":"https://binbaz.org.sa/fatwas/22447/وقت-العمرة-برمضان-وحكم-تكرارها-واهداىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فضل العمرة في رمضان سواء كان في أوله أو آخره.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":2390,"question":"الساعة الأولى يوم الجمعة؟","title":"متى تكون الساعة الأولى يوم الجمعة؟","answer":"الجواب:\nالأقرب أنها بعد طلوع الشمس، بعد ارتفاع الشمس، يُشرع للإنسان الجلوس في مسجده حتى ترتفع الشمس، والأقرب أنها بعد طلوع الشمس، بعد ارتفاع الشمس.","link":"https://binbaz.org.sa/fatwas/22515/متى-تكون-الساعة-الاولى-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الساعة الأولى يوم الجمعة.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":2646,"question":"بالنسبة لفضل الصيام في مكة: هل يَفْرُق بين الصيام في مكة وفي غيرها؟","title":"هل للصيام في مكة فَضْلٌ عن غيرها؟","answer":"الجواب: نعم كل الأعمال في مكة لها فضل، كل الأعمال الصالحة، إلا الصلاة فإنها تضاعف بمائة ألف، وما سواها له فضل وله مزيّة، لكن ما في حصر محدود، والمدينة لها نصيبها من ذلك، لكن مكة بنص الرسول ﷺ مضاعفة فيها الأعمال، لكن الصلاة بَيَّن النبي ﷺ بأنها بمائة ألف صلاة، وفي مسجد النبي ﷺ خير من ألف صلاة فيما سواه، أما ما سوى ذلك فيه فضل ولكن لم يُحدَّد بشيء، تضاعف الأجور؛ من صوم، من صدقة، تسبيح، وتهليل، وقراءة قرآن، وطواف، فيه خير كثير.","link":"https://binbaz.org.sa/fatwas/22782/هل-للصيام-في-مكة-فضل-عن-غيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فضل الصيام في مكة وفي غيره.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":2799,"question":"المدينة أو من خصوصيات مكة: مضاعفة الحسنات؟","title":"هل تضاعف الأعمال في المدينة النبوية؟","answer":"الجواب: المدينة لها نصيبها؛ لأنها هي البلد الثاني بعد الحرم، بعد مكة، تضاعف فيها الأعمال، لكن الصلاة في مسجد النبي ﷺ خير من ألف صلاة، أما بقية المضاعفات فلا يعلمها إلا الله، ما بيّنها النبي ﷺ فلا يعلمها إلا الله، مثل مضاعفة الحسنات في مكة لا نعلم عددها إلا ما يتعلق بالصلاة في المسجد الحرام، فإن الرسول ﷺ قال: خير من مائة ألف مما سواه لكن مثل أجر الصيام وأجر الصدقات مضاعف، لكن لا نعلم الكمية، لم يرد في السنة الصحيحة بيان الكمية إلا فيما يتعلق بالصلاة.","link":"https://binbaz.org.sa/fatwas/22947/هل-تضاعف-الاعمال-في-المدينة-النبوية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تضاعف الأعمال في المدينة.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":2830,"question":"أفضل الأيام عند الله  يوم النَّحْر أم يوم عرفة؟","title":"هل أفضل الأيام يوم النَّحْر أم يوم عرفة؟","answer":"الجواب: أفضل الأيام يوم النَّحْر ثم يوم عرفة.\nس: ويوم الجمعة؟\nالشيخ: يوم الجمعة أفضل أيام الأسبوع.","link":"https://binbaz.org.sa/fatwas/22979/هل-افضل-الايام-يوم-النحر-ام-يوم-عرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أفضل الأيام عند الله يوم النحر أم يوم عرفة.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":2952,"question":"أيهما أفضل: الاعتمار في أشهر الحج أم في رمضان؟","title":"هل العمرة في رمضان أفضل مِن أشهر الحج؟","answer":"الجواب: في رمضان، يقول النبي ﷺ: عمرة في رمضان تعدل حِجَّة. وفي لفظ: حِجة معي.","link":"https://binbaz.org.sa/fatwas/23108/هل-العمرة-في-رمضان-افضل-من-اشهر-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العمرة في أشهر الحج أم في رمضان.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":3321,"question":"السيئات في رمضان هل تُضاعف؟","title":"هل تُضاعف السيئاتُ في رمضان؟","answer":"الجواب: تضاعف من جهة الكيفية، السيئات تُضاعف من جهة الكيفية لا من جهة العدد، أما الحسنات تضاعف كيفية وعددًا، أما السيئات بواحدة دائمًا؛ لكن سيئة في رمضان أو في الحرم أعظم من سيئة في غير رمضان وفي غير الحرم، من جهة الكيفية والإثم.","link":"https://binbaz.org.sa/fatwas/23487/هل-تضاعف-السيىات-في-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تضاعف السيئات في رمضان.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":4687,"question":"بالنسبة للبلد الحرام هل تُضاعف فيه السيئات؟","title":"ما كيفية مضاعفة السيئات في البلد الحرام؟","answer":"الجواب: السيئات ما تُضاعف إلا من جهة الكيفية، السيئة بواحدةٍ كما قال الله جلَّ وعلا: فَلَا يُجْزَى إِلَّا مِثْلَهَا [الأنعام:160]، لكن سيئة في الحرم أعظم، يعني من جهة الإثم، لا تعدد، لا تكون عشرًا ولا غيرها، لكن أعظم، سيئة الحرم وسيئة المدينة وسيئة الشام وسيئة رمضان أعظم، يعني أشد في الإثم، ولكن لا تتعدد، فكل سيئةٍ بواحدةٍ، لكن السيئة من جهة الكيفية -من جهة عظم الإثم- تختلف.","link":"https://binbaz.org.sa/fatwas/24979/ما-كيفية-مضاعفة-السيىات-في-البلد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُضاعف السيئات في البلد الحرام.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":5555,"question":"يوم الخامس عشر من شعبان؟","title":"هل صح شيء في فضل منتصف شعبان؟","answer":"الجواب: ما صحَّ فيه شيء، نصف شعبان لم يصحّ فيه شيء عن النبي ﷺ، لا يخصّ ليله بقيامٍ، ولا نهاره بصيامٍ.[1]","link":"https://binbaz.org.sa/fatwas/31507/هل-صح-شيء-في-فضل-منتصف-شعبان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 018.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":6118,"question":"إذا صادف يوم العيد يوم الجمعة، وصليت صلاة العيد، فهل الأفضل أن أصلي صلاة الجمعة، أم أقضيها ظهرًا؟","title":"حكم ترك صلاة الجمعة لمن صلى صلاة العيد","answer":"الجواب: الأفضل أن يصلي صلاة الجمعة؛ لأن الرسول كان يصليها -عليه الصلاة والسلام- كان يصلي الجمعة، والعيد جميعًا، ولكن رخص للناس من حضر صلاة العيد، من شاء صلى الجمعة، ومن شاء صلى ظهرًا، النبي ﷺ كان يجمع، فإذا صلى الجمعة مع الناس؛ كان أفضل حتى يحصل له فضل الجمعة، وسماع الخطبة ... وإن صلى الظهر، ولم يصل الجمعة يوم العيد؛ لأنه قد صلى العيد؛ جاز ذلك على الصحيح، كما جاءت به السنة عن النبي ﷺ أنه رخص لمن حضر العيد بترك الجمعة. ولكن إذا حضر الجمعة، وصلاها؛ كان أفضل لما فيه من الخير العظيم، والنبي ﷺ كان يصلي الجمعة، ويصلي العيد جميعًا، كما قال النعمان فيما رواه مسلم في الصحيح قال: \"كان يقرأ في الجمعة بسبح، والغاشية، وهكذا في العيد، وربما اجتمعا في يوم فقرأ بهما جميعًا في الصلاتين، صلاة العيد، وصلاة الجمعة\" رواه مسلم في الصحيح.","link":"https://binbaz.org.sa/fatwas/1530/حكم-ترك-صلاة-الجمعة-لمن-صلى-صلاة-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_460.mp3","categories":["صلاة العيدين","صلاة الجمعة","فضائل الأزمنة والأمكنة"]},{"id":6134,"question":"أي الأوقات تتحرى الساعة المذكورة يوم الجمعة، أيوم الجمعة أم في العصر، أم بعد صلاة الجمعة مباشرة؟","title":"الأوقات التي تتحرى فيها ساعة الجمعة","answer":"الجواب: الله -جل وعلا- جعل فيها ساعة يقبل فيها الدعاء، وهي ساعة قليلة لا يوافقها عبد مسلم وهو قائم يصلي إلا أعطاه الله سؤاله، فهي ساعة عظيمة قليلة، جاء في بعض الروايات عند مسلم: أنها حين يجلس الإمام على المنبر يوم الجمعة إلى أن تقضى الصلاة، هكذا جاء، رواه مسلم من حديث أبي موسى مرفوعًا، وأعله بعضهم بأنه مرسل. وجاء أيضًا في حديث جابر، وعبدالله بن سلام: أنها بعد العصر إلى غروب الشمس، وجاء في بعض الأحاديث: أنها آخر ساعة من يوم الجمعة، وكلها ليست قطعية، لكنها هذه أحرى، أحراها، وأرجاها ما بين الجلوس على المنبر، إلى أن تقضى الصلاة، وما بين صلاة العصر إلى غروب الشمس، هذه أرجاها، وبقيت يوم الجمعة كلها يرجى فيها إجابة الدعوة. جميع أوقات يوم الجمعة كلها ترجى فيها إجابة الدعوة، لكن أرجاها ما بين جلوس الإمام على المنبر إلى أن تقضى الصلاة، وما بين صلاة العصر إلى غروب الشمس، هذان الوقتان أرجى الأوقات كما جاء في ذلك الأحاديث، وبقيت الجمعة ترجى فيها هذه الإجابة، فينبغي الإكثار في يوم الجمعة من الدعوات، ينبغي الإكثار من الدعاء؛ لعله يصادف هذه الساعة المباركة.","link":"https://binbaz.org.sa/fatwas/1579/الاوقات-التي-تتحرى-فيها-ساعة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_480.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":6578,"question":"التهنئة في العيد -أي عيد الفطر وعيد الأضحى- وما يفعله الناس من المصافحة، أو الالتزام، أو التعانق، والرسائل بعد صلاة العيدين، حتى ولو كانوا معًا قبل الصلاة، هل لهذا أصل؟ وإن كان لذلك أصل فما هي الصفة الصحيحة؟","title":"حكم التهنئة يوم العيد والمعانقة والمصافحة","answer":"الجواب: ما أعلم لهذا أصلًا، لكن كان السلف يهنئ بعضهم بعضا: تقبل الله منك، تقبل الله منا ومنك، فإذا قابله، وصافحه، وقال: تقبل الله منا ومنك، وعيدك مبارك؛ فلا نعلم به بأسًا، هذا من العهد الأول بارك الله لك في العيد، أو تقبل الله منا ومنك، وكلمات نحو هذا، لا بأس، يكفي. أما المعانقة لا نعلم لها أصلًا، لكن معروفة بين الناس فيما بينهم إذا تقابلوا، وإلا تركها أولى، تكفي المصافحة، أو الدعاء بالقبول عند اللقاء، يكفي.","link":"https://binbaz.org.sa/fatwas/2433/حكم-التهنىة-يوم-العيد-والمعانقة-والمصافحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_960.mp3","categories":["صلاة العيدين","صلاة الجمعة","فضائل الأزمنة والأمكنة"]},{"id":6635,"question":"يقولون عن الرسول أنه يقول: ما بين منبري وبيتي .. فهل روضات الإنسان..؟","title":"من خصوصيات مسجد النبي عليه الصلاة والسلام","answer":"الجواب: لا، هذا خاص بالنبي ﷺ.. صح عن رسول الله ﷺ قال: ما بين بيتي، ومنبري روضة من رياض الجنة هذا خاص ببيت النبي ﷺ أما البيوت الأخرى لا. السؤال: والروضة.. الجواب: وأما المساجد الأخرى لا، الناس يسمونها عامة روضة .. لكن ما لها الفضل، هذا ليس لها الفضل، ما قاله النبي صلى الله في مسجده.. السؤال:.. الجواب: لها أفضلية السبق في المسابقة، أن يسابق إلى قرب الإمام، يكون أفضل، أن يسابق إلى قرب الإمام يكون أفضل، نعم.","link":"https://binbaz.org.sa/fatwas/2484/من-خصوصيات-مسجد-النبي-عليه-الصلاة-والسلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_1011.mp3","categories":["فضائل الأزمنة والأمكنة"]},{"id":8617,"question":"هذه رسالة من السائل عبدالله سرور لم يذكر عنواناً يقول فيها: الصلاة في مكة وفي بيوتها هل هي مضاعفة مثل الصلاة عند الكعبة؟","title":"عموم مضاعفة الصلاة في الحرم كله","answer":"الجواب: نعم، الصواب أن المضاعفة تعم الحرم كله، حرم مكة، ولكن فعلها حول الكعبة يكون أفضل من جهة الجمع لكثرة الجمع، من جهة أنه محل متفق عليه من جهة الفضل، ولكن من جهة عموم المضاعفة فالصواب أنها تعم، تعم جميع مساجد مكة وحرم مكة كله إلى الأميال إلى حدود الحرم؛ لأن الكل يسمى مسجد حرام، جميع الحرم يسمى المسجد الحرام، والصلاة فيه مضاعفة لكنها فيما حول الكعبة ومع الجماعة التي حول الكعبة مع الإمام الذي في المسجد الحرام نفسه يكون أفضل، ذلك أفضل وأكمل لقربه من الكعبة ولأنه محل متفق عليه، ولكثرة الجمع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6741/عموم-مضاعفة-الصلاة-في-الحرم-كله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21007.mp3","categories":["فضائل الأزمنة والأمكنة","المساجد ومواضع السجود"]},{"id":8778,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":8779,"question":"يقول: ما كيفية زيارة مسجد الرسول ﷺ؟ وهل الأدعية الواردة في كتيبات الزيارة التي يزور بها المزورون في الأماكن المقدسة صحيحة أم لا؟ وأرشدونا عن كيفية الزيارة الصحيحة؟","title":"ما هي الأعمال المستحبة عند زيارة مسجد النبي؟","answer":"الجواب: زيارة مسجد الرسول ﷺ سنة؛ لأنها أحد المساجد الثلاثة، وقد قال فيه النبي ﷺ: لا تشد الرحال إلا إلى ثلاثة مساجد: المسجد الحرام، ومسجدي هذا، والمسجد الأقصى فشد الرحال إلى هذه الثلاثة سنة وقربة وطاعة، وقال عليه الصلاة والسلام: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام فقصد هذا المسجد العظيم للصلاة فيه والقراءة فيه والتعبد أمر مطلوب وشرعي، وهكذا المسجد الحرام مسجد مكة، وهكذا المسجد الأقصى القدس، كل هذه الثلاثة المساجد قصدها وشد الرحيل إليها قربة وطاعة، فإذا وصل إليها المؤمن صلى فيها ما يسر الله، وتعبد فيها بالاعتكاف أو بالقراءة أو بحضور حلقات العلم، كل هذا طيب. وأما مكة فيحصل فيها أيضاً زيادة على هذا: الطواف بالكعبة، ويمكن أداء العمرة كذلك والحج في وقته، هذا يختص بمكة، العمرة والحج هذا من خصائص مكة. أما مسجد النبي ﷺ فالزائر له مثل بقية المساجد يصلي فيه، يتعبد بالقراءة، بحضور حلقات العلم بالإكثار من ذكر الله ، كل هذا مطلوب، وهكذا الاعتكاف، وهكذا المسجد الأقصى إذا زاره المؤمن صلى فيه وقرأ فيه وذكر الله فيه وتعبد فيه بأنواع العبادة من الصلاة والذكر والقراءة والاعتكاف ونحو ذلك كل هذا مشروع.\nويستحب لمن زار المدينة: أن يسلم على النبي ﷺ وعلى صاحبيه، فيتوجه بعدما يصلي ركعتين في المسجد إذا صلاها في الروضة كان أفضل، إذا صلى الركعتين في الروضة كان أفضل وإن صلاها في بقية المسجد كفى ذلك، ثم بعد هذا يتوجه إلى قبره عليه الصلاة والسلام فيقف أمامه عليه الصلاة والسلام ويسلم عليه عليه الصلاة والسلام ويقول: السلام عليك يا رسول الله ورحمة الله وبركاته، صلى الله وسلم عليك وعلى آلك وأصحابك، ويدعو له، يقول: جزاك الله عن أمتك خيراً، أشهد أنك قد بلغت الرسالة، وأديت الأمانة، ونصحت الأمة، وجاهدت في الله حق جهاده.. إذا قال هذا الكلام هذا كلام طيب وصحيح وصدق، ثم يتقدم قليلاً فيسلم على الصديق  أبو بكر فيقول: السلام عليك يا أبا بكر الصديق ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً.. رضي الله عنك، ثم يتقدم قليلاً ويسلم على عمر الفاروق  عمر بن الخطاب فيقول: السلام عليك يا عمر بن الخطاب ورحمة الله وبركاته، جزاك الله عن أمة محمد خيراً ورضي الله عنك، ويدعو لهما ثم ينصرف، هذا هو المشروع في السلام على الرسول ﷺ وعلى صاحبيه الصديق وعمر رضي الله تعالى عنهما.\nويشرع له أيضاً أن يزور البقيع فيسلم على أصحاب البقيع ويدعو لهم بالمغفرة والرحمة؛ لأن الرسول كان يزورهم عليه الصلاة والسلام، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم دار قوم مؤمنين وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، نسأل الله لنا ولكم العافية. هكذا يسلم على أهل القبور ويدعو لهم: اللهم اغفر لهم وارحمهم، مثلما دعا النبي ﷺ لأهل البقيع، وهكذا يستحب له أن يزور الشهداء شهداء أحد فيدعو لهم ويستغفر لهم ويترحم عليهم  وأرضاهم، هذا هو المشروع.\nأما ما يفعله بعض الجهلة كونه يدعو النبي ﷺ، أو يستغيث به، أو يتمسح بجدران الحجرة هذا منكر لا يجوز، ولكن يسلم وهو واقف من غير أن يمسح الحجرة أو القضبان أو الجدران أو الأسطوانات، كل هذا غير مشروع بل بدعة، لا يتمسح بالجدران ولا بالأسطوانات ولا بقضبان الشبك ولا بغير هذا، ولكن يقف أمام النبي ﷺ ويسلم وهكذ أمام الصديق ، وأمام عمر رضي الله عنهما ويسلم ثم ينصرف، هذا هو المشروع، ولا يدعو النبي ﷺ ولا يدعو غيره، لا يقل: يا رسول الله! انصرني أو اشفع لي، أو أغثني، أو المدد المدد، هذا منكر لا يجوز بل هو من الشرك الأكبر، وهكذا عند الصحابيين الصديق وعمر رضي الله عنهما لا يقل لهما: أغيثاني أو انصراني أو المدد المدد كما يفعل بعض الجهلة عند بعض القبور، هذا منكر، بل هذا من الشرك، طلب الغوث من الميت والمدد من الميت هذا من الشرك الأكبر عند أهل العلم، وهكذا عند زيارة قبور البقيع لا يقل لهم: المدد المدد، ولا انصروني، أو اشفوا مريضي، أو اشفعوا لي لا، ولكن يسلم عليهم ويدعو لهم بالمغفرة والرحمة ثم ينصرف، وهكذا شهداء أحد إذا سلم عليهم يدعو لهم كما دعا لهم النبي ﷺ ويستغفر لهم ويترحم عليهم وينصرف.\nويستحب لمن زار المدينة أيضاً أن يزور مسجد قباء ويصلي فيه ركعتين كما كان النبي يزوره عليه الصلاة والسلام، وأخبر ﷺ أن من زاره.. أن من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة. فزيارة مسجد قباء سنة وقربة تأسياً بالنبي عليه الصلاة والسلام في ذلك، هذا هو المشروع لمن زار المدينة، أما كونه يقصد محلات أخرى آبار أو مساجد أخرى أو بقاع هذا غير مشروع، المشروع لمن زار المدينة هو ما ذكرنا: أولاً: الصلاة في مسجد النبي ﷺ، ثم السلام على النبي ﷺ وعلى صاحبيه، ثم زيارة البقيع، ثم زيارة الشهداء، ثم زيارة مسجد قباء، كل هذه سنة وليست واجبة، لو أنه ما زارها ما فيه شيء، ولكن هذا سنة ومستحب وليس بواجب. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6933/ما-هي-الاعمال-المستحبة-عند-زيارة-مسجد-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_219/21906.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":11356,"question":"يسأل سماحتكم فيقول: ماذا كان يفعل النبي ﷺ في يوم الجمعة؟","title":"تخصيص يوم الجمعة بعبادة","answer":"الجواب:  لا أعلم أنه كان يخصه بشيء -عليه الصلاة والسلام- يوم الجمعة لا يخص بصيام، ولا يخص ليلته بالقيام، ولكنه يوم فاضل، يوم قراءة يوم ذكر، يوم صلاة تعبد، فلا أعلم شيئًا كان يخصه النبي ﷺ يوم الجمعة، إلا أنه روي عن النبي ﷺ: من قرأ سورة الكهف يوم الجمعة أضاء له نور بين المشرق والمغرب أو كما قال، عليه الصلاة والسلام. وجاء ذلك عن أبي سعيد الخدري بإسناد صحيح أنه كان يقرأ الكهف يوم الجمعة، وروي عن ابن عمر أيضًا فهذا مستحب قراءة الكهف يوم الجمعة، أما تخصيصها بصيام أو بصدقات خاصة، أو بزيارة القبور أو ما أشبه ذلك فلا أعلم له أصلًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9529/تخصيص-يوم-الجمعة-بعبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37806.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":12408,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12415,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات، تقول المرسلة (ب. س) من الرياض تسأل وتقول: ورد في الحديث أن من جلس بعد صلاة الفجر إلى طلوع الشمس على مصلاه يذكر الله حتى يصلي ركعتي الفجر؛ كتبت له أجر حجة وعمرة، وقال أهل العلم: إن المرأة إذا فعلت ذلك في بيتها يرجى لها نصف الأجر،  هناك أناس يقولون: إنه يشترط لهذه الجلسة ألا يتحدث مع أحد في أمور الدنيا، هل هذا الكلام صحيح، وإذا كان صحيحًا، فماذا أفعل إذا كانت والدتي كبيرة في السن، وقد أخبرتها بذلك، ولكنها تنسى، وتحدثني بأمور دنيوية، لا ضرورة لها خلال جلستي هذه، فهل إذا جلست مبتغيةً الثواب من الله، ولكن تحدثت مع أمي، وأجبتها حرصًا على رضاها، هل أكون قد أديت العبادة كما ينبغي؟","title":"هل تدخل المرأة في فضل الجلوس بعد الفجر إلى الإشراق؟","answer":"الجواب:  نعم نعم جمعت بين الخيرين، بين الذكر، وبين رضا الوالدة، وبرها من أهم المهمات، فالحديث معها إذا طلبت الحديث أمر مطلوب، ومشروع، ولا يضر، ولا يقطع الجلسة، ولا يؤثر عليك، فمن جلس في مصلاه يذكر الله، يصلي على النبي ﷺ ويسبح، ويدعو حتى تطلع الشمس، ثم يصلي ركعتين سنة الضحى، هاتان الركعتان يقال لها: سنة الضحى، ويسميها العامة سنة الإشراق، وهي سنة الضحى مبكرة، فله أجر، جاء في الحديث: أجر حجة وعمرة تامتين. ولا فرق بين الرجال والنساء، المرأة كالرجل ما هو النصف، نصف حجة، لا حجة تامة، الرجل والمرأة سواء في هذا، الحديث عام للرجال والنساء، فالمرأة في بيتها تجلس في مصلاها، والرجل في مصلاه في المسجد حتى تطلع الشمس، ثم يصلي ركعتين، هذا كله خير عظيم، يشتغل بذكر الله، بالدعاء، بقراءة القرآن، الحمد لله، وإذا تكلم مع أخيه في شيء دعت إليه الحاجة؛ فلا بأس، أو تكلمت المرأة مع زوجها، أو مع والدتها، أو مع غيرهم في الحاجة؛ فلا بأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الذين قالوا: إن المرأة لها نصف الأجر ليسوا على صواب؟ الشيخ: غلط، لا الأجر عام، الحكم واحد، فالرجل والمرأة سواء. المقدم: بارك الله فيكم، وسواء كان ذلك في المسجد، أو في بيتها. الشيخ: نعم نعم في المسجد، أو في البيت. المقدم: بارك الله فيكم، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10620/هل-تدخل-المراة-في-فضل-الجلوس-بعد-الفجر-الى-الاشراق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40208.mp3","categories":["صيام التطوع","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":12674,"question":"بعد هذا ننتقل إلى المزاحمية عبر رسالة بعثت بها إحدى الأخوات المستمعات تقول السائلة أم عبادة ..، أم عبادة لها جمع من الأسئلة من بينها سؤال يقول: قال الرسول ﷺ: من صلى الفجر في جماعة، ثم قعد يذكر الله تعالى حتى تطلع الشمس، ثم صلى ركعتين؛ كانت كأجر حجة وعمرة تامة تامة تامة هل هذا الفضل يكون للنساء أيضًا إذا صلين في بيوتهن، وهل يشترط لهذا الفضل أن تكون الصلاة في جماعة أي: هل يكون للمرأة إذا صلت في بيتها وحدها في غير جماعة، وقعدت تذكر الله حتى تطلع الشمس ذلك الفضل؟ وجهونا جزاكم الله خيرًا.","title":"دخول المرأة في حديث: (من صلى الفجر...)","answer":"الجواب:  نعم يرجى لها ذلك، يرجى لها هذا الخير العظيم، نعم.  المقدم: عن الصلاة التي ذكرت في هذا الحديث: هل تكون بعد أن تطلع الشمس مباشرة؟ الشيخ: بعد ارتفاع الشمس قيد رمح، يعني: بعد ربع ساعة، أو نحوها من طلوع الشمس. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10884/دخول-المراة-في-حديث-من-صلى-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41703.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":13332,"question":"هذا السائل عبدالرحمن من المدينة النبوية استعرضنا سؤالًا له، بقي له سؤالان، يقول: ثبت عن الرسول ﷺ أنه قال: من أتى مسجد قباء، وصلى فيه؛ كان كأجر عمرة والسؤال سماحة الشيخ: هل يشترط لهذه الصلاة الخروج، خصوصًا من البيت بنية الصلاة في قباء للحصول على أجر العمرة؟ أم أنه يأتي بأي صلاة تجزي؟ فمثلًا: إذا صليت الجمعة في قباء، فهل يكون لي أجر عمرة بمشيئة الله؟","title":"شرط الحصول على أجر العمرة للمصلي في قباء","answer":"الجواب:\n\nثبت عن النبي ﷺ: \"أنه كان يزور قباء كل سبت، راكبًا وماشيًا\" -عليه الصلاة والسلام- وقال -عليه الصلاة والسلام-: من تطهر في بيته، ثم أتى مسجد قباء، فصلى فيه ركعتين؛ كان كعمرة هذا الفضل ذكره لمن يتطهر من بيته، ويخرج قاصدًا للصلاة في قباء؛ يحصل له هذا الأجر.\n\nأما من صلى فيه كالعادة بغير قصد من بيته؛ فله أجر، وله خير عظيم، لكن لا يتوفر فيه الشرط المذكور، إنما يحصل هذا لمن تطهر في بيته، وخرج من بيته قاصدًا للصلاة في مسجد قباء، كما كان النبي يفعل، عليه الصلاة والسلام.\n\nأما الصلاة فيه من غير قصد من البيت، بل مر، وصلى به، أو كان من جيرانه، وصلى فيه الفروض؛ يرجى له خير عظيم؛ لكن لا يتوفر فيه ما قاله النبي ﷺ إلا بالشروط التي قالها: من تطهر في بيته، ثم أتى مسجد قباء، وصلى فيه يعني: يخرج من بيته قاصدًا، فإذا خرج من بيته قاصدًا يوم الجمعة، أو غير الجمعة، وصلى فيه؛ يحصل له هذا الأجر، والحمد لله. نعم.\n\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11618/شرط-الحصول-على-اجر-العمرة-للمصلي-في-قباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54202.mp3","categories":["شروح الحديث","فضائل الأزمنة والأمكنة","فضائل الأعمال"]},{"id":13730,"question":"تقول في ثاني أسئلتها: هل لعمرة سبع وعشرين من رمضان مزية على بقية أيام رمضان؟","title":"ما مزية العمرة في سبعة وعشرين من رمضان؟","answer":"الجواب:  مزيتها أنها قد توافق ليلة القدر؛ لأن ليلة سبعة وعشرين أرجى الليالي في ليلة القدر، فالناس يحرصون على ذلك يرجون أن توافق هذه الليلة حتى تكون خيرًا من ألف عمرة، كما قال -جل وعلا-: لَيْلَةُ الْقَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ [القدر:3] يعني: العمل فيها خير من عمل في ألف شهر، فالعمرة فيها خير من العمرة في ألف شهر، وهكذا، هذا وجه تحري الناس لهذه الليلة، لكن لا ينبغي إذا كان زحامًا ومشقة، لا ينبغي؛ لأن ليلة القدر غير معلومة، قد تكون في ليلة سبعة وعشرين، وقد تكون في غيرها. ثم لو كانت في ليلة سبعة وعشرين؛ فالزحام الذي يضر الناس لا ينبغي، ولا يجوز، لا يجوز أن يخاطر بنفسه، ولا بزوجته في زحام يرجو ليلة القدر، الأمر فيها واسع فضل ما هو بشيء واجب، الحمد لله صادفها، أو ما صادفها، له أجر عظيم في العمرة، والحمد لله.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12101/ما-مزية-العمرة-في-سبعة-وعشرين-من-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54516.mp3","categories":["فضائل الأزمنة والأمكنة","فضائل الحج والعمرة","فضائل رمضان"]},{"id":14231,"question":"يقول في فقرته الأخيرة: الصلاة في مسجد قباء هل هو بأجر عمرة؟ أم يشترط الخروج من البيت متوضئًا بنية الذهاب إلى قباء وصلاة ركعتين للعمرة؟","title":"هل يُنال أجر العمرة بمجرد الصلاة في مسجد قباء؟","answer":"الجواب: كان النبي ﷺ يزور مسجد قباء ويصلي فيه كل سبت، ويقول: من تطهر في بيته ثم أتى مسجد قباء فصلى فيه ركعتين كان كعمرة فإذا خرج من بيته قاصدًا العمرة يكون هذا أكمل، يتطهر في بيته ويقصد مسجد قباء ويصلي فيه، وإن مر عليه من أي جهة وصلى فيه قربة وطاعة، لكن إذا تطهر في بيته يكون أكمل ثم أتى مسجد قباء فصلى فيه ركعتين يكون كعمرة كما قال النبي عليه الصلاة والسلام.\nالمقدم: اللهم صل على سيدنا محمد.","link":"https://binbaz.org.sa/fatwas/12690/هل-ينال-اجر-العمرة-بمجرد-الصلاة-في-مسجد-قباء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54904.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16520,"question":"هل من السنة أن يذهب من يسكن في المدينة المنورة كل أسبوع إلى مسجد قباء؟ أم أن هذه مقولة لا دليل لها؟","title":"مشروعية زيارة مسجد قباء كل أسبوع","answer":"الجواب: هذا هو الأفضل، كما فعله النبي ﷺ كان يزور قباء كل سبت، يعني: كل أسبوع، فالأفضل لمن كان في المدينة أن يزور قباء في الأسبوع مرة... يوم السبت، أو غيره، كما فعله النبي -عليه الصلاة والسلام- ويصلي فيه ركعتين، أو أكثر، ثم ينصرف، اقتداء بالنبي الكريم، عليه الصلاة والسلام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15247/مشروعية-زيارة-مسجد-قباء-كل-اسبوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75704.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16524,"question":"من المدينة المنورة رسالة بعث بها أحد الإخوة المستمعين من هناك، ورمز إلى اسمه بالحرفين (م) و (ح) يسأل عدة أسئلة في أحدها يقول: هل صلاة النافلة في المسجد النبوي تعدل أفضل صلاة؟ أم أن مضاعفة الصلاة مختصة بالفريضة فقط؟ جزاكم الله خيرًا.","title":"مضاعفة أجر الصلاة في المسجد النبوي","answer":"الجواب: المضاعفة عامة للفرض، والنفل في مسجد النبي ﷺ وفي المسجد الحرام، والنبي ﷺ لم يخص الفريضة، بل قال: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه، إلا المسجد الحرام وقال ﷺ: صلاة في المسجد الحرام بمائة صلاة في مسجد النبي ﷺ يعني: بمائة ألف في المساجد الأخرى، وهذا يعم النفل، والفرض. لكن النفل في البيت أفضل، ويكون له أجر أكثر، والمرأة في بيتها أفضل، ولها أجر أكثر، وإذا صلى الرجل في مسجد النبي ﷺ فرضًا، أو نفلًا؛ فله هذه المضاعفة، لكن ومع هذا المشروع له أن يصلي النافلة في البيت: سنة الظهر... سنة المغرب... سنة العشاء... سنة الفجر في البيت أفضل، وتكون له المضاعفة أكثر؛ لأن الرسول ﷺ قال للناس: أفضل صلاة المرء في بيته إلا المكتوبة وهو يخاطبهم وهو في المدينة -عليه الصلاة والسلام- فدل ذلك على أن صلاتهم في بيوتهم -صلاة النافلة- أفضل، وتكون مضاعفتها أكثر، وهكذا في المسجد الحرام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15245/مضاعفة-اجر-الصلاة-في-المسجد-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75703.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16949,"question":"يسأل أخونا (ع. ف. غ) فيقول: ما حكم من هم بمعصيةٍ في مكة المكرمة، ولكنه لم يفعلها؟ هل يعد كمن فعلها؟ وهل للإقامة في مكة المكرمة، والمدينة المنورة آداب، وأحكام خاصة بهما؟","title":"حكم الهم بالمعصية في مكة أو المدينة","answer":"الجواب: من هم بالمعصية في الحرم الشريف المكي؛ استحق العقاب، هذا شيء خاص بالحرم المكي؛ لأن الله يقول سبحانه: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ [الحج:25] هذا وعيد شديد، يدل على أنه إذا هم بالمعصية ولو لم يفعل، يستحق العقاب، فالواجب الحذر على من كان في مكة الحذر، وهكذا في المدينة يجب الحذر؛ لأن الرسول ﷺ حرم المدينة كما حرم إبراهيم مكة، فالواجب الحذر من المعاصي كلها، والهمة بها، والعزم عليها. أما في غير مكة، والمدينة؛ فالهم لا يؤاخذ به، إذا هم بالسيئة فلم يعملها؛ لم تكتب عليه، فإن عملها كتبت سيئة واحدة، فإن تركها من أجل الله، كتبت حسنة، كما جاء في الحديث الصحيح عن النبي ﷺ.  فالإنسان إذا هم بالسيئة في أي مكان -غير مكة والمدينة- له ثلاث حالات: إحداها: أن يهم بالسيئة، ثم يتركها تشاغلًا عنها، هذا ليس عليه شيء، الثانية: يهم بها، ثم يدعها لله، خوفًا من الله، هذه تكتب له حسنة، الثالث: هم بها وعمل ما استطاع من الفعل السيئ، فهذا يؤاخذ بذلك، للحديث الصحيح، يقول ﷺ: إذا التقى المسلمان بسيفيهما؛ فالقاتل، والمقتول في النار قيل: يا رسول الله! هذا القاتل، فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه يعني: قد فعل أشياء، فهكذا الإنسان إذا هم بالسيئة، وهتك الحرز، وحاول أخذ المال، يأثم بهذه الأشياء؛ لأنها كلها محرمة عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15741/حكم-الهم-بالمعصية-في-مكة-او-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82806.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16953,"question":"يسأل ويقول: هل للإقامة في مكة المكرمة، والمدينة المنورة آداب، وأحكام خاصة بهما؟","title":"بعض أحكام وآداب الإقامة بمكة والمدينة","answer":"الجواب: نعم، يجب على من أقام بهما أن يحذر المعاصي والسيئات، أكثر من حذره في غيرها، يجب على من أقام بهما أن يحذر المعاصي والسيئات، أكثر من الحذر لو أقام في غيرهما؛ لأن السيئات فيهما عظيمة، وإثمها أكبر، وإن كانت سيئة واحدة في كل مكان، لكن سيئة في مكة أعظم في الإثم في سيئة في الطائف، أو الرياض، أو أبها، أو أمريكا، أو غير ذلك، وحسنة في مكة أعظم من حسنة في غيرها، تضاعف، وهكذا في المدينة تضاعف بأضعاف كثيرة، في الكم، والكيفية، لكن السيئة تضاعف في الكيفية، لا في الكم، السيئة في مكة، والمدينة تضاعف من جهة الكيفية، من جهة عظم الإثم، لا من جهة التعدد، السيئة واحدة، فمن أقام في المدينة، أو مكة فالواجب عليه أن يحذر السيئات، وأن يحرص على البعد عنها، والسلامة من أسبابها، ويشرع له الاجتهاد في الخيرات، والأعمال الصالحات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15742/بعض-احكام-واداب-الاقامة-بمكة-والمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82807.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16954,"question":"يسأل أخونا (ع. ف. غ) فيقول: ما حكم من هم بمعصيةٍ في مكة المكرمة، ولكنه لم يفعلها؟ هل يعد كمن فعلها؟ وهل للإقامة في مكة المكرمة، والمدينة المنورة آداب، وأحكام خاصة بهما؟","title":"حكم الهم بالمعصية في مكة أو المدينة","answer":"الجواب: من هم بالمعصية في الحرم الشريف المكي؛ استحق العقاب، هذا شيء خاص بالحرم المكي؛ لأن الله يقول سبحانه: وَمَنْ يُرِدْ فِيهِ بِإِلْحَادٍ بِظُلْمٍ نُذِقْهُ مِنْ عَذَابٍ أَلِيمٍ [الحج:25] هذا وعيد شديد، يدل على أنه إذا هم بالمعصية ولو لم يفعل، يستحق العقاب، فالواجب الحذر على من كان في مكة الحذر، وهكذا في المدينة يجب الحذر؛ لأن الرسول ﷺ حرم المدينة كما حرم إبراهيم مكة، فالواجب الحذر من المعاصي كلها، والهمة بها، والعزم عليها. أما في غير مكة، والمدينة؛ فالهم لا يؤاخذ به، إذا هم بالسيئة فلم يعملها؛ لم تكتب عليه، فإن عملها كتبت سيئة واحدة، فإن تركها من أجل الله، كتبت حسنة، كما جاء في الحديث الصحيح عن النبي ﷺ.  فالإنسان إذا هم بالسيئة في أي مكان -غير مكة والمدينة- له ثلاث حالات: إحداها: أن يهم بالسيئة، ثم يتركها تشاغلًا عنها، هذا ليس عليه شيء، الثانية: يهم بها، ثم يدعها لله، خوفًا من الله، هذه تكتب له حسنة، الثالث: هم بها وعمل ما استطاع من الفعل السيئ، فهذا يؤاخذ بذلك، للحديث الصحيح، يقول ﷺ: إذا التقى المسلمان بسيفيهما؛ فالقاتل، والمقتول في النار قيل: يا رسول الله! هذا القاتل، فما بال المقتول؟ قال: لأنه كان حريصًا على قتل صاحبه يعني: قد فعل أشياء، فهكذا الإنسان إذا هم بالسيئة، وهتك الحرز، وحاول أخذ المال، يأثم بهذه الأشياء؛ لأنها كلها محرمة عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15741/حكم-الهم-بالمعصية-في-مكة-او-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82806.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":16958,"question":"يسأل ويقول: هل للإقامة في مكة المكرمة، والمدينة المنورة آداب، وأحكام خاصة بهما؟","title":"بعض أحكام وآداب الإقامة بمكة والمدينة","answer":"الجواب: نعم، يجب على من أقام بهما أن يحذر المعاصي والسيئات، أكثر من حذره في غيرها، يجب على من أقام بهما أن يحذر المعاصي والسيئات، أكثر من الحذر لو أقام في غيرهما؛ لأن السيئات فيهما عظيمة، وإثمها أكبر، وإن كانت سيئة واحدة في كل مكان، لكن سيئة في مكة أعظم في الإثم في سيئة في الطائف، أو الرياض، أو أبها، أو أمريكا، أو غير ذلك، وحسنة في مكة أعظم من حسنة في غيرها، تضاعف، وهكذا في المدينة تضاعف بأضعاف كثيرة، في الكم، والكيفية، لكن السيئة تضاعف في الكيفية، لا في الكم، السيئة في مكة، والمدينة تضاعف من جهة الكيفية، من جهة عظم الإثم، لا من جهة التعدد، السيئة واحدة، فمن أقام في المدينة، أو مكة فالواجب عليه أن يحذر السيئات، وأن يحرص على البعد عنها، والسلامة من أسبابها، ويشرع له الاجتهاد في الخيرات، والأعمال الصالحات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15742/بعض-احكام-واداب-الاقامة-بمكة-والمدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82807.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":17459,"question":"هذه سائلة من القصيم حصة تقول في هذا  هل صحيح بأن نقل ماء زمزم من مكانه إلى مكان آخر يذهب بذلك أثر هذا الماء، وتنقص قيمته؟","title":"بركة زمزم باقية وإن انتقل إلى مكان آخر","answer":"الجواب: ليس بصحيح، ماء زمزم على بركته، وعلى ما فيه من الخير، ولو نقل إلى الشام، واليمن، أو أمريكا هو ماء زمزم، ماء مبارك، سواء شرب في مكة، أو نقل إلى أمريكا، أو إلى نجد، أو إلى الشام، أو إلى أي مكان، فضله وما فيه من النفع موجود، وإن نقل، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16323/بركة-زمزم-باقية-وان-انتقل-الى-مكان-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77211.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":17821,"question":"مكة والمدينة لهما منزلة كبيرة في قلوبنا أيهما أفضل الإقامة في مكة أم في المدينة وذلك للعبادة؟","title":"أفضلية الإقامة بمكة على المدينة","answer":"الجواب: مكة أفضل، ثم المدينة بعدها، والإقامة بمكة أفضل من المدينة، ثم المدينة كما جاء في الأحاديث، الصلاة في مكة بمائة ألف صلاة، في المسجد الحرام وفي الحرم مائة ألف ويقول النبي ﷺ في المدينة: صلاة في مسجدي هذا خير من ألف صلاة فيما سواه إلا المسجد الحرام، وصلاة في المسجد الحرام بمائة ألف صلاة في مسجدي هذا فرق عظيم، والحسنات في مكة مضاعفة أكثر من مضاعفتها في المدينة، ولكن على من أقام في مكة والمدينة أن يحذر المعاصي؛ لأنها عظيمة أيضًا، على كل واحد أن يحذر المعاصي ويبتعد عنها، ويحاسب نفسه ويجاهدها حتى لا يقع فيما حرم الله في هذا البلد الأمين أو في المدينة المنورة، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، أحسن الله إليكم وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16814/افضلية-الاقامة-بمكة-على-المدينة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77901.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":18288,"question":"من الأخت المستمعة (ع. ع. س) من جدة، حي النزهة رسالة ضمنتها قضية، تقول فيها:سمعت من معلمة الدين في مدرستي أنه من المستحب صيام العشرة الأيام الأولى من شهر ذي الحجة، وأن العمل الصالح في هذه الأيام هو أحب الأعمال إلى الله  وإذا كان هذا صحيحًا، فمن الطبيعي أن يكون اليوم العاشر من ذي الحجة، والذي يلي يوم عرفة، هو أول أيام التشريق، وهي أيام عيد للمسلمين، الحجاج وغيرهم، ومما أعلمه هو أنه لا يجوز صيام أيام العيد، فما تفسيركم لذلك، إن كان يحرم صيامه، وهو من الأيام العشرة الأولى؟وما هو اليوم العاشر البديل إن كان لا يصام؟ وهل إذا صمت هذه الأيام يجب علي أن أصومها كلها؟ علمًا بأنني صمت السادس، والسابع، والثامن، والتاسع، ولم أصم العاشر، مع توضيح عدد أيام عيدي الفطر، والأضحى، ففيها اختلاف؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"بعض أحكام عشر ذي الحجة وأيام التشريق","answer":"الجواب: العشر تطلق على التسع، ويوم العيد لا يحسب منها، عشر ذي الحجة، يقال: عشر ذي الحجة، والمراد التسع، التي يتعلق بالصيام، ويوم العيد لا يصام بإجماع المسلمين، بإجماع أهل العلم، فإذا قيل: صوم العشر، يعني معناها: التسع، يأتي آخرها يوم عرفة، وصيامها مستحب، وقربة، وروي عن النبي أنه كان يصومها عليه السلام، وقال فيها: \"إن العمل فيها أحب إلى الله من بقية الأيام\"، فإنه عليه الصلاة والسلام قال: ما من أيامٍ العمل الصالح فيهن أحب إلى الله من هذه الأيام العشر، قالوا: يا رسول الله! ولا الجهاد في سبيل الله؟ قال: ولا الجهاد في سبيل الله، إلا رجل خرج بنفسه وماله، ثم لم يرجع من ذلك بشيء، فهذه العشر مستحب فيها الذكر، والتكبير، والقراءة، والصدقات، منها العاشر. أما الصوم لا، ليس العاشر منها، الصوم يختص بعرفة، وما قبلها، فإن يوم العيد لا يصام عند جميع أهل العلم، لكن فيما يتعلق بالذكر، والدعاء، والصدقات، فهو داخل في العشر، ويوم العيد. وأيام العيد ثلاثة، غير يوم العيد، الحادي عشر، والثاني عشر، والثالث عشر، الجميع أربعة، يوم العيد، وثلاث أيام التشريق، هذا هو الصواب عند أهل العلم، يقول النبي ﷺ: أيام التشريق، أيام أكلٍ وشرب، وذكر الله ، فهي أربعة بالنسبة إلى ذي الحجة: يوم النحر، وأيام التشريق الثلاثة. أما في رمضان؛ فالعيد يوم واحد، فقط، أول يوم من شوال، هذا هو العيد، وما سواه ليس بعيد، له أن يصوم الثاني من شهر شوال، فالعيد يختص باليوم الأول في شوال، فقط. نعم. المقدم: جزاكم الله خيرًا، وبالنسبة للأضحى؟ جزاكم الله خيرًا. الشيخ: أربعة، مثلما تقدم، عيد الأضحى أربعة أيام، يوم العاشر، والحادي عشر، والثاني عشر، والثالث عشر، هذه كلها أيام عيد لا تصام، إلا أيام التشريق تصام بالنسبة إلى من عجز عن الهدي، هدي التمتع والقران، رخصة خاصة لمن عجز عن الهدي، هدي التمتع والقران، أن يصوم الثلاثة التي هي أيام التشريق: الحادي عشر، والثاني عشر، والثالث عشر، ثم يصوم السبعة في أهله، بين أهله، أما يوم العيد فلا يصام، لا عن هدي، ولا عن غيره، بإجماع المسلمين. نعم. المقدم: جزاكم الله خيرًا، أما عيد الفطر فهو يوم واحد فقط. الشيخ: نعم، يوم واحد فقط. المقدم: جزاكم الله خيرًا، وأحسن إليكم، تذكر -سماحة الشيخ- أنها صامت بعض أيام العشر من ذي الحجة، فتذكر أنها صامت مثلاً السابع، والثامن، والتاسع، ما هو توجيهكم والحال ما ذكر. الشيخ: أعد. المقدم: تقول إنها صامت بعض أيام العشر الأول من شهر ذي الحجة. الشيخ: لا مانع إذا صامت السابع، والثامن، والتاسع؛ لا حرج، أو صامت أكثر من ذلك، المقصود أنها أيام، أيام ذكر، وأيام صوم، فإن صامت التسعة كلها، فهذا طيب وحسن، وإن صامت بعضها، فكله طيب، وإذا اقتصرت على صوم عرفة فقط، فهو أفضلها يوم عرفة، يوم عرفة الذي قال فيه النبي ﷺ: إن صوم عرفة، أحتسب على الله أن يكفر به السنة التي قبله، والتي بعده يوم عظيم، يستحب صيامه، لأهل الحضر والبدو جميعًا، يوم عرفة، إلا الحجاج، فإنهم لا يصومون يوم عرفة، وهكذا بقية الأيام، من أول ذي الحجة إلى يوم عرفة، يستحب صيامها، تسعة، لكن أفضلها يوم عرفة، يصام في الحضر، والبادية، سنة، إلا يوم العيد فلا يصام، لا في الحج، ولا في غيره. نعم، والحجاج لا يصومون يوم عرفة، السنة للحاج أن لا يصوم يوم عرفة بل يكون مفطرًا كما أفطر النبي ﷺ يوم عرفة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17339/بعض-احكام-عشر-ذي-الحجة-وايام-التشريق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73201.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":18498,"question":"سماحة الشيخ! يقول هذا السائل: بأن العلماء قالوا بأن أفضل أوقات لقيام الليل هو الثلث الأخير، ولكنني لا أعرف هل يبدأ تقسيم هذا الليل من وقت الغروب حتى شروقها، أم من وقت غروبها حتى وقت صلاة الفجر؟","title":"كيفية تقسيم الليل لمعرفة الثلث الأخير","answer":"الجواب: الليل من غروب الشمس إلى طلوع الفجر، هذا الليل، من غروب الشمس إلى طلوع الفجر الصادق، وأفضل أوقاته الثلث الأخير لقول النبي ﷺ: ينزل ربنا إلى السماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له حتى ينفجر الفجر، هذا الوقت هو الوقت العظيم وقت التنزل الإلهي، وقت دعوة الرب للعباد أن يسألوه، وأن يضرعوا إليه جل وعلا، هذا هو أفضل الوقت وبعده جوف الليل. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17595/كيفية-تقسيم-الليل-لمعرفة-الثلث-الاخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78605.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]},{"id":19561,"question":"ورد أن ماء زمزم لما شرب له، فهل يلزم أن يقرأ فيه شيء من القرآن، ويشربه المريض؟ أم نكتفي بشربه بدون قراءة؟","title":"ما ورد في فضل ماء زمزم","answer":"الجواب: ماء زمزم شفاء لما شرب له، من غير حاجة إلى قراءة، يقول ﷺ: إنها مباركة، إنها طعام طعم، وشفاء سقم فالشرب منها، والتروش منها، كل ذلك من أسباب الشفاء والعافية، ويروى عنه ﷺ أنه قال: ماء زمزم لما شرب له لكن في سنده ضعف، ولكن الثابت أنه قال ﷺ: إنها مباركة، إنها طعام طعم، وشفاء سقم وكان النبي ﷺ إذا فرغ من طوافه لما فرغ من طوافه يوم العيد يوم النحر أتاها وشرب عليه الصلاة والسلام. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18810/ما-ورد-في-فضل-ماء-زمزم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94709.mp3","categories":["الرقائق","فضائل الأزمنة والأمكنة"]}]
